 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }}
 * @returns {object}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate date
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate lines array
  if (!lines || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and enrich lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Determine discount: explicit discountPercent (even 0) takes precedence over tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customerResult.value.tier];
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate and get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    enrichedLines.push({
      sku: line.sku,
      name: productResult.value.name,
      qty: line.qty,
      unitPrice: productResult.value.unitPrice,
      vatRate: productResult.value.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line item.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  let vat = 0;

  for (const line of invoice.lines) {
    const lineamt = lineTotal(line);
    subtotal += lineamt;

    const lineDiscount = lineamt * (line.discountPercent ?? 0) / 100;
    const roundedLineDiscount = roundCents(lineDiscount);
    discount += roundedLineDiscount;

    const lineAmountAfterDiscount = lineamt - roundedLineDiscount;
    const lineVat = lineAmountAfterDiscount * (line.vatRate ?? 0) / 100;
    vat += roundCents(lineVat);
  }

  const total = Math.max(0, subtotal - discount + vat);
  return { subtotal, discount, vat, total };
}

/**
 * Add or update a line on an invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }}
 * @returns {object}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const discount = discountPercent !== undefined ? discountPercent : TIER_DISCOUNTS[customerResult.value.tier];
  if (typeof discount !== 'number' || discount < 0 || discount > 100) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const newLines = invoice.lines.map(line => ({ ...line }));
  const existingIndex = newLines.findIndex(line => line.sku === sku);

  if (existingIndex >= 0) {
    newLines[existingIndex] = {
      ...newLines[existingIndex],
      qty: newLines[existingIndex].qty + qty,
    };
  } else {
    newLines.push({
      sku: sku,
      name: productResult.value.name,
      qty: qty,
      unitPrice: productResult.value.unitPrice,
      vatRate: productResult.value.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {object}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const lineIndex = invoice.lines.findIndex(line => line.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((_, index) => index !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning a number and changing status to 'issued'.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {Array<string>} existingNumbers
 * @returns {object}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

